function reverseVowels(str) {
  const arr = str.split('');
  let l = 0, r = arr.length - 1;
  const vowels = 'aeiouAEIOU';
  while (l < r) {
    while (l < r && !vowels.includes(arr[l])) l++;
    while (l < r && !vowels.includes(arr[r])) r--;
    [arr[l], arr[r]] = [arr[r], arr[l]];
    l++; r--;
  }
  return arr.join('');
}
